class Position:
    def __init__(self, symbol, qty, avg_cost):
        self.symbol = symbol
        self.qty = qty
        self.avg_cost = avg_cost

    def market_value(self, price):
        return self.qty * price

    def pnl(self, price):
        return (price - self.avg_cost) * self.qty

    def __str__(self):
        return f'{self.symbol}: {self.qty} @ {self.avg_cost}'

pos = Position('AAPL', 250, 41.75)
print(pos.market_value(42.25))   # 10562.5
print(pos.pnl(42.25))            # 125.0
print(pos)                       # AAPL: 250 @ 41.75

position = {'symbol': 'AAPL', 'qty': 250, 'avg_cost': 41.75}
