class Position:
    def __init__(self, symbol, qty, avg_cost):
        if qty <= 0:
            raise ValueError('qty must be positive')
        self.symbol = symbol
        self.qty = qty
        self.avg_cost = avg_cost

safe = Position('AAPL', 250, 41.75)    # fine
bad = Position('AAPL', -100, 41.75)    # raises ValueError: qty must be positive

class Position:
    def __init__(self, symbol, qty):
        self.symbol = symbol
        self.qty = qty

    def market_value(self, price):
        return self.qty * price

class HedgedPosition(Position):
    def __init__(self, symbol, qty, hedge_qty):
        super().__init__(symbol, qty)     # parent set-up first
        self.hedge_qty = hedge_qty

    def market_value(self, price):        # override
        return (self.qty - self.hedge_qty) * price

h = HedgedPosition('AAPL', 250, 150)
print(h.market_value(42.25))   # 4225.0 - net of the hedged 150 shares

