class Portfolio:
    def __init__(self):
        self.positions = {}

    def add(self, symbol, qty, avg_cost):
        self.positions[symbol] = {'qty': qty, 'avg_cost': avg_cost}

    def market_value(self, prices):
        total = 0
        for symbol, pos in self.positions.items():
            total += pos['qty'] * prices[symbol]
        return total

book = Portfolio()
