class Portfolio:
    def __init__(self):
        self.positions = {}

    def add(self, symbol, qty, avg_cost):
        self.positions[symbol] = {'qty': qty, 'avg_cost': avg_cost}

    def pnl(self, prices):
        total = 0
        for symbol, pos in self.positions.items():
            total += (prices[symbol] - pos['avg_cost']) * pos['qty']
        return total

    def __str__(self):
        return f'Portfolio with {len(self.positions)} positions'

book = Portfolio()
book.add('AAPL', 250, 41.75)
book.add('MSFT', 100, 43.00)
print(book.pnl({'AAPL': 42.25, 'MSFT': 43.50}))   # 175.0
print(book)                                        # Portfolio with 2 positions
```
AAPL contributes (42.25 - 41.75) x 250 = 125.0 and MSFT contributes (43.50 - 43.00) x 100 = 50.0, for a total unrealised PnL of \$175.00.

